## Code Example
```javascript
// Minimal hook sketch
function useCRDTSync() {
  const [state, setState] = React.useState(null);
  React.useEffect(() => {
    const sub = subscribeToDeltaStream((d) => {
      // applyDelta via NativeModules.RNCRDT.mergeDelta(d)
    });
    return () => sub.unsubscribe();
  }, []);
  const applyLocalChange = (c) => {
    // convert to delta and send to Rust
    NativeModules.RNCRDT.mergeDelta(c);
  };
  return { state, applyLocalChange, startSync: ()=>{} };
}
